import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position
  const pos = config.scenePosition || {};
  group.position.set(
    pos.x ?? 0,
    pos.y ?? 0,
    pos.z ?? 0
  );

  if (pos.rotationXYZ && pos.rotationXYZ.length === 3) {
    group.rotation.order = 'XYZ';
    group.rotation.fromArray(pos.rotationXYZ);
  }

  if (pos.scaleXYZ && pos.scaleXYZ.length === 3) {
    group.scale.fromArray(pos.scaleXYZ);
  }

  // Create textured plane
  const planeGeometry = new THREE.PlaneGeometry(1, 0.625);
  const planeMaterial = new THREE.MeshBasicMaterial({
    map: ctx.textureLoader.load(config.imageUrl || ''),
    transparent: true
  });
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Render text via fontAtlas
  if (ctx.fontAtlas && config.textContent) {
    const textContent = Array.isArray(config.textContent) 
      ? config.textContent[0] 
      : config.textContent;

    let textMesh = null;
    if (typeof ctx.fontAtlas === 'function') {
      textMesh = ctx.fontAtlas(textContent, {
        fontFamily: 'Lora',
        fontSize: 0.34,
        fontWeight: 400,
        color: config.colors?.ink || '#16161d',
        align: 'center'
      });
    } else if (ctx.fontAtlas && ctx.fontAtlas.render) {
      textMesh = ctx.fontAtlas.render(textContent, {
        fontFamily: 'Lora',
        fontSize: 0.34,
        fontWeight: 400,
        color: config.colors?.ink || '#16161d',
        align: 'center'
      });
    }

    if (textMesh instanceof THREE.Object3D) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    if (planeMaterial.map) {
      planeMaterial.map.dispose();
    }
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
